/**
 * Thread-safe LRU cache with TTL expiration, backed by a circular buffer.
 *
 * "Thread-safe" here means safe under async concurrency (Node.js event loop).
 * A mutex serialises every mutating operation so interleaved async calls
 * never see half-written state.
 */

class CircularBuffer {
  #buf;
  #capacity;
  #head = 0; // points to the next write position
  #size = 0;
  #index = new Map(); // key -> buffer slot
  #accessOrder = []; // most-recent at end
  #ttl; // ms, 0 = no expiry
  #mutex = Promise.resolve();

  /**
   * @param {number} capacity - Maximum number of entries (>= 1).
   * @param {number} [ttlMs=0] - Time-to-live in milliseconds. 0 = no expiry.
   */
  constructor(capacity, ttlMs = 0) {
    if (!Number.isInteger(capacity) || capacity < 1)
      throw new RangeError("capacity must be a positive integer");
    if (typeof ttlMs !== "number" || ttlMs < 0)
      throw new RangeError("ttlMs must be a non-negative number");

    this.#capacity = capacity;
    this.#ttl = ttlMs;
    this.#buf = new Array(capacity).fill(null);
  }

  // ── public async API (mutex-protected) ────────────────────────────

  async get(key) {
    return this.#lock(() => this.#get(key));
  }

  async put(key, value) {
    return this.#lock(() => this.#put(key, value));
  }

  async delete(key) {
    return this.#lock(() => this.#delete(key));
  }

  async has(key) {
    return this.#lock(() => this.#index.has(key) && !this.#isExpired(key));
  }

  async size() {
    return this.#lock(() => this.#size);
  }

  async keys() {
    return this.#lock(() => {
      this.#evictExpired();
      return [...this.#index.keys()];
    });
  }

  async clear() {
    return this.#lock(() => {
      this.#buf.fill(null);
      this.#index.clear();
      this.#accessOrder = [];
      this.#head = 0;
      this.#size = 0;
    });
  }

  // ── sync peek (non-mutating, for tests / inspection) ────────────

  peek(key) {
    if (!this.#index.has(key)) return undefined;
    if (this.#isExpired(key)) return undefined;
    return this.#buf[this.#index.get(key)].value;
  }

  get capacity() {
    return this.#capacity;
  }

  // ── internals (must only run inside #lock) ───────────────────────

  #get(key) {
    this.#evictExpired();
    if (!this.#index.has(key)) return undefined;
    if (this.#isExpired(key)) {
      this.#removeEntry(key);
      return undefined;
    }
    this.#touch(key);
    return this.#buf[this.#index.get(key)].value;
  }

  #put(key, value) {
    this.#evictExpired();
    if (this.#index.has(key)) {
      const slot = this.#index.get(key);
      this.#buf[slot] = { key, value, ts: Date.now() };
      this.#touch(key);
      return;
    }
    if (this.#size === this.#capacity) {
      this.#evictLRU();
    }
    const slot = this.#head;
    this.#buf[slot] = { key, value, ts: Date.now() };
    this.#index.set(key, slot);
    this.#accessOrder.push(key);
    this.#size++;
    this.#head = (this.#head + 1) % this.#capacity;
  }

  #delete(key) {
    this.#evictExpired();
    if (!this.#index.has(key)) return false;
    this.#removeEntry(key);
    return true;
  }

  #isExpired(key) {
    if (this.#ttl === 0) return false;
    const slot = this.#index.get(key);
    if (slot === undefined) return true;
    return Date.now() - this.#buf[slot].ts >= this.#ttl;
  }

  #evictExpired() {
    if (this.#ttl === 0) return;
    for (const key of [...this.#index.keys()]) {
      if (this.#isExpired(key)) this.#removeEntry(key);
    }
  }

  #evictLRU() {
    for (let i = 0; i < this.#accessOrder.length; i++) {
      const key = this.#accessOrder[i];
      if (this.#index.has(key)) {
        this.#removeEntry(key);
        return;
      }
    }
  }

  #removeEntry(key) {
    this.#index.delete(key);
    this.#size--;
  }

  #touch(key) {
    const idx = this.#accessOrder.indexOf(key);
    if (idx !== -1) this.#accessOrder.splice(idx, 1);
    this.#accessOrder.push(key);
  }

  #lock(fn) {
    const next = this.#mutex.then(fn, fn);
    this.#mutex = next.catch(() => {});
    return next;
  }
}

module.exports = { CircularBuffer };

const { CircularBuffer } = require("./circular_buffer");

let passed = 0;
let failed = 0;
const failures = [];

function assert(cond, msg) {
  if (!cond) {
    failed++;
    failures.push(msg);
  } else {
    passed++;
  }
}

function assertEq(actual, expected, msg) {
  if (actual !== expected) {
    failed++;
    failures.push(`${msg}: got ${JSON.stringify(actual)}, expected ${JSON.stringify(expected)}`);
  } else {
    passed++;
  }
}

async function assertThrows(fn, errType, msg) {
  try {
    await fn();
    failed++;
    failures.push(`${msg} — expected error, none thrown`);
  } catch (e) {
    if (!(e instanceof errType)) {
      failed++;
      failures.push(`${msg} — expected ${errType.name}, got ${e.constructor.name}`);
    } else {
      passed++;
    }
  }
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

async function run() {
  // ── Constructor validation ────────────────────────────────────────
  console.log("constructor validation");
  assertThrows(() => new CircularBuffer(0), RangeError, "capacity 0");
  assertThrows(() => new CircularBuffer(-1), RangeError, "negative capacity");
  assertThrows(() => new CircularBuffer(1.5), RangeError, "float capacity");
  assertThrows(() => new CircularBuffer(3, -1), RangeError, "negative ttl");
  assertThrows(() => new CircularBuffer(3, "bad"), RangeError, "string ttl");

  // ── Basic put/get ─────────────────────────────────────────────────
  console.log("basic put/get");
  const cb = new CircularBuffer(3);
  await cb.put("a", 1);
  await cb.put("b", 2);
  await cb.put("c", 3);
  assertEq(await cb.get("a"), 1, "get a");
  assertEq(await cb.get("b"), 2, "get b");
  assertEq(await cb.get("c"), 3, "get c");
  assertEq(await cb.size(), 3, "size after 3 puts");

  // ── Update existing key ───────────────────────────────────────────
  console.log("update existing key");
  await cb.put("a", 10);
  assertEq(await cb.get("a"), 10, "updated value");
  assertEq(await cb.size(), 3, "size unchanged after update");

  // ── Overwrite same key doesn't consume extra slot ─────────────────
  const cb2 = new CircularBuffer(2);
  await cb2.put("x", 1);
  await cb2.put("x", 2);
  await cb2.put("x", 3);
  assertEq(await cb2.size(), 1, "repeated put keeps size 1");
  assertEq(await cb2.get("x"), 3, "latest value kept");

  // ── LRU eviction ──────────────────────────────────────────────────
  console.log("lru eviction");
  const lru = new CircularBuffer(3);
  await lru.put("a", 1);
  await lru.put("b", 2);
  await lru.put("c", 3);
  // access 'a' so it becomes most-recent
  await lru.get("a");
  // inserting 'd' should evict 'b' (least recently used)
  await lru.put("d", 4);
  assertEq(await lru.get("a"), 1, "a still present after touch");
  assertEq(await lru.get("b"), undefined, "b evicted");
  assertEq(await lru.get("c"), 3, "c still present");
  assertEq(await lru.get("d"), 4, "d inserted");

  // ── Evict oldest when no access pattern ───────────────────────────
  console.log("evict oldest (no access)");
  const lru2 = new CircularBuffer(2);
  await lru2.put("x", 10);
  await lru2.put("y", 20);
  await lru2.put("z", 30); // should evict x
  assertEq(await lru2.get("x"), undefined, "x evicted");
  assertEq(await lru2.get("y"), 20, "y kept");
  assertEq(await lru2.get("z"), 30, "z kept");

  // ── Delete ────────────────────────────────────────────────────────
  console.log("delete");
  const del = new CircularBuffer(3);
  await del.put("a", 1);
  await del.put("b", 2);
  assertEq(await del.delete("a"), true, "delete existing");
  assertEq(await del.get("a"), undefined, "deleted key gone");
  assertEq(await del.size(), 2, "size after delete");
  assertEq(await del.delete("a"), false, "delete non-existent");

  // ── Has ───────────────────────────────────────────────────────────
  console.log("has");
  const has = new CircularBuffer(2);
  await has.put("a", 1);
  assertEq(await has.has("a"), true, "has existing");
  assertEq(await has.has("b"), false, "has non-existent");

  // ── Keys ──────────────────────────────────────────────────────────
  console.log("keys");
  const keys = new CircularBuffer(3);
  await keys.put("a", 1);
  await keys.put("b", 2);
  await keys.put("c", 3);
  const k = await keys.keys();
  assertEq(k.length, 3, "keys count");
  assert(k.includes("a") && k.includes("b") && k.includes("c"), "keys content");

  // ── Clear ─────────────────────────────────────────────────────────
  console.log("clear");
  const clr = new CircularBuffer(3);
  await clr.put("a", 1);
  await clr.put("b", 2);
  await clr.clear();
  assertEq(await clr.size(), 0, "size after clear");
  assertEq(await clr.get("a"), undefined, "a gone after clear");

  // ── TTL expiration ────────────────────────────────────────────────
  console.log("ttl expiration");
  const ttl = new CircularBuffer(3, 100);
  await ttl.put("a", 1);
  assertEq(await ttl.get("a"), 1, "get before expiry");
  await sleep(120);
  assertEq(await ttl.get("a"), undefined, "expired on get");
  assertEq(await ttl.peek("a"), undefined, "expired on peek");

  // ── TTL: has returns false after expiry ───────────────────────────
  console.log("ttl has");
  const ttlHas = new CircularBuffer(2, 80);
  await ttlHas.put("x", 10);
  assertEq(await ttlHas.has("x"), true, "has before expiry");
  await sleep(100);
  assertEq(await ttlHas.has("x"), false, "has after expiry");

  // ── TTL: keys excludes expired ────────────────────────────────────
  console.log("ttl keys");
  const ttlKeys = new CircularBuffer(3, 80);
  await ttlKeys.put("a", 1);
  await sleep(50);
  await ttlKeys.put("b", 2); // b is fresher
  await sleep(50); // 'a' now ~100ms old, 'b' ~50ms
  const kk = await ttlKeys.keys();
  assertEq(kk.length, 1, "only 1 key after first expires");
  assert(kk.includes("b"), "b survives");

  // ── TTL: update resets timer ──────────────────────────────────────
  console.log("ttl update resets timer");
  const ttlUpd = new CircularBuffer(2, 100);
  await ttlUpd.put("a", 1);
  await sleep(80);
  await ttlUpd.put("a", 2); // reset timer
  await sleep(80); // total 160ms since first put, but only 80 since update
  assertEq(await ttlUpd.get("a"), 2, "updated entry survives past original ttl");

  // ── TTL: delete removes expired cleanly ───────────────────────────
  console.log("ttl delete expired");
  const ttlDel = new CircularBuffer(2, 50);
  await ttlDel.put("a", 1);
  await sleep(70);
  assertEq(await ttlDel.delete("a"), false, "delete expired returns false");

  // ── Capacity 1 ────────────────────────────────────────────────────
  console.log("capacity 1");
  const c1 = new CircularBuffer(1);
  await c1.put("only", 42);
  assertEq(await c1.get("only"), 42, "single entry");
  await c1.put("new", 99);
  assertEq(await c1.get("only"), undefined, "evicted by new");
  assertEq(await c1.get("new"), 99, "new entry");

  // ── Circular wrap-around ──────────────────────────────────────────
