  // all 5 stored keys should be retrievable
  const storedKeys = await conc.keys();
  assertEq(storedKeys.length, 5, "5 unique keys after concurrent put");
  for (const k of storedKeys) {
    const v = await conc.get(k);
    assert(typeof v === "number", `key ${k} has numeric value`);
  }

