  console.log("concurrent get/put mix");
  const mix = new CircularBuffer(10, 500);
  const ops = [];
  for (let i = 0; i < 100; i++) {
    if (i % 3 === 0) ops.push(mix.put(`k${i % 20}`, i));
    else if (i % 3 === 1) ops.push(mix.get(`k${i % 20}`));
    else ops.push(mix.delete(`k${i % 20}`));
  }
