  peek.peek("a");
  await peek.put("c", 3);
  assertEq(await peek.get("a"), undefined, "peeked entry still evicts as LRU");

  // ── No TTL (0) means entries never expire ─────────────────────────
  console.log("no ttl");
  const noTtl = new CircularBuffer(2, 0);
  await noTtl.put("a", 1);
  await sleep(50);
  assertEq(await noTtl.get("a"), 1, "entry survives with ttl=0");

  // ── Large capacity stress ─────────────────────────────────────────
  console.log("large capacity stress");
  const big = new CircularBuffer(1000);
  for (let i = 0; i < 5000; i++) {
    await big.put(i, i * 2);
  }
  assertEq(await big.size(), 1000, "size at capacity");
  assertEq(await big.get(4999), 9998, "latest entry correct");

  // ── Summary ───────────────────────────────────────────────────────
  console.log(`\n${passed} passed, ${failed} failed`);
  if (failures.length) {
    console.error("\nFailures:");
    failures.forEach((f) => console.error(`  - ${f}`));
  }
  if (failed > 0) process.exit(1);
}

